import "testing"
func TestModeCannotChangeDuringRequest(t *testing.T) {
 a := &Agent{busy:true}
 if a.SetMode("execute") != ErrSessionBusy { t.Fatal("busy guard missing") }
 a.busy=false
 if err:=a.SetMode("execute");err!=nil {t.Fatal(err)}
}

